import{_ as l,o as e,c as o,a5 as i}from"./chunks/framework.DJo0M80U.js";const _=JSON.parse(`{"title":"浏览器事件循环的各个阶段（定时器、I-O 回调、空闲、渲染、微任务）","description":"示例代码 // 模拟 I/O 回调（例如网络请求） function simulateAsyncIO(callback) \\\\{ setTimeout(() \\\\ callback(), 0); // 模拟异步 I/O \\\\} // 1. 定义宏任务和微任务 console.log('。","frontmatter":{"title":"浏览器事件循环的各个阶段（定时器、I-O 回调、空闲、渲染、微任务）","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","工程化、质量与性能"],"description":"示例代码 // 模拟 I/O 回调（例如网络请求） function simulateAsyncIO(callback) \\\\{ setTimeout(() \\\\ callback(), 0); // 模拟异步 I/O \\\\} // 1. 定义宏任务和微任务 console.log('。","sidebarWeight":57,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/性能优化/深度面试：浏览器中与任务执行、渲染和事件循环/浏览器事件循环的各个阶段（定时器、I-O 回调、空闲、渲染、微任务）.md"},"headers":[],"relativePath":"posts/Vue系统教程/06-工程化、质量与性能/深度面试：浏览器中与任务执行、渲染和事件循环/浏览器事件循环的各个阶段（定时器、I-O 回调、空闲、渲染、微任务）.md","filePath":"posts/Vue系统教程/06-工程化、质量与性能/深度面试：浏览器中与任务执行、渲染和事件循环/浏览器事件循环的各个阶段（定时器、I-O 回调、空闲、渲染、微任务）.md"}`),s={name:"posts/Vue系统教程/06-工程化、质量与性能/深度面试：浏览器中与任务执行、渲染和事件循环/浏览器事件循环的各个阶段（定时器、I-O 回调、空闲、渲染、微任务）.md"};function r(n,t,a,g,c,u){return e(),o("div",null,[...t[0]||(t[0]=[i('<div><h1 id="浏览器事件循环的各个阶段-定时器、i-o-回调、空闲、渲染、微任务" tabindex="-1">浏览器事件循环的各个阶段（定时器、I-O 回调、空闲、渲染、微任务） <a class="header-anchor" href="#浏览器事件循环的各个阶段-定时器、i-o-回调、空闲、渲染、微任务" aria-label="Permalink to &quot;浏览器事件循环的各个阶段（定时器、I-O 回调、空闲、渲染、微任务）&quot;">​</a></h1><blockquote><p>本节目标：理解“浏览器事件循环的各个阶段（定时器、I-O 回调、空闲、渲染、微任务）”的核心思路，并能把它用于实际开发或面试表达。 <strong>示例代码</strong> _// 模拟 I/O 回调（例如网络请求）_function simulateAsyncIO(callback) { setTimeout(() =&gt; callback(), 0); <em>// 模拟异步 I/O</em>} _// 1. 定义宏任务和微任务_console.log(&#39;Script start&#39;); _// 定时器阶段（setTimeout）_setTimeout(() =&gt; { console.log(&#39;setTimeout callback&#39;); <em>// 添加微任务</em> Promise.resolve().then(() =&gt; { console.log(&#39;setTimeout microtask&#39;); });}, 0); _// I/O 回调阶段（模拟网络请求）_simulateAsyncIO(() =&gt; { console.log(&#39;I/O callback&#39;); <em>// 添加微任务</em> Promise.resolve().then(() =&gt; { console.log(&#39;I/O microtask&#39;); });}); _// 空闲阶段（requestIdleCallback）_requestIdleCallback((deadline) =&gt; { console.log(<code>requestIdleCallback, timeRemaining: ${deadline.timeRemaining()}</code>);}); _// 渲染阶段（requestAnimationFrame）_requestAnimationFrame(() =&gt; { console.log(&#39;requestAnimationFrame callback&#39;); <em>// 修改 DOM，触发回流与重绘</em> document.body.style.background = &#39;lightblue&#39;;}); _// 微任务（Promise）_Promise.resolve().then(() =&gt; { console.log(&#39;Initial Promise microtask&#39;);}); console.log(&#39;Script end&#39;);</p></blockquote><p><strong>HTML（用于 DOM 操作）</strong> &lt;!DOCTYPE html&gt;&lt;html&gt;&lt;body&gt; &lt;h1&gt;Event Loop Demo&lt;/h1&gt; &lt;script src=&quot;script.js&quot;&gt;&lt;/script&gt;&lt;/body&gt;&lt;/html&gt;</p><p><strong>事件循环阶段与执行顺序分析</strong> JavaScript 的事件循环按以下阶段运行，每个阶段处理特定类型的任务，并在每个宏任务后清空微任务队列。我们将按照代码的实际执行顺序，结合事件循环阶段进行分析。 <strong>1. 同步代码执行（初始宏任务）</strong></p><ul><li><strong>阶段</strong>：主线程（同步代码不是事件循环的一部分，但作为初始宏任务运行）。</li><li><strong>执行</strong>： <ul><li>console.log(&#39;Script start&#39;) 输出：Script start。</li><li>setTimeout 注册一个定时器回调，加入宏任务队列（定时器阶段）。</li><li>simulateAsyncIO 调用 setTimeout(..., 0)，注册 I/O 回调，加入宏任务队列（I/O 阶段）。</li><li>requestIdleCallback 注册空闲回调，加入空闲任务队列。</li><li>requestAnimationFrame 注册渲染回调，加入渲染任务队列。</li><li>Promise.resolve().then(...) 注册微任务，加入微任务队列。</li><li>console.log(&#39;Script end&#39;) 输出：Script end。</li></ul></li><li><strong>输出</strong>： Script startScript end</li></ul><p><strong>2. 微任务阶段（清空微任务队列）</strong></p><ul><li><strong>阶段</strong>：在初始宏任务完成后，清空微任务队列。</li><li><strong>执行</strong>： <ul><li>执行 Promise.resolve().then(...) 的回调，输出：Initial Promise microtask。</li></ul></li><li><strong>输出</strong>： Initial Promise microtask</li></ul><p><strong>3. 定时器阶段（宏任务队列）</strong></p><ul><li><strong>阶段</strong>：检查宏任务队列，执行到期的 setTimeout 回调。</li><li><strong>执行</strong>： <ul><li>setTimeout 回调执行，输出：setTimeout callback。</li><li>在回调中，Promise.resolve().then(...) 注册一个新的微任务，加入微任务队列。</li></ul></li><li><strong>输出</strong>： setTimeout callback</li></ul><p><strong>4. 微任务阶段（清空微任务队列）</strong></p><ul><li><strong>阶段</strong>：在定时器阶段的宏任务后，清空微任务队列。</li><li><strong>执行</strong>： <ul><li>执行 setTimeout 回调中的微任务，输出：setTimeout microtask。</li></ul></li><li><strong>输出</strong>： setTimeout microtask</li></ul><p><strong>5. I/O 回调阶段（宏任务队列）</strong></p><ul><li><strong>阶段</strong>：处理宏任务队列中的 I/O 回调（simulateAsyncIO 的 setTimeout）。</li><li><strong>执行</strong>： <ul><li>I/O 回调执行，输出：I/O callback。</li><li>在回调中，Promise.resolve().then(...) 注册一个新的微任务，加入微任务队列。</li></ul></li><li><strong>输出</strong>： I/O callback</li></ul><p><strong>6. 微任务阶段（清空微任务队列）</strong></p><ul><li><strong>阶段</strong>：在 I/O 回调阶段后，清空微任务队列。</li><li><strong>执行</strong>： <ul><li>执行 I/O 回调中的微任务，输出：I/O microtask。</li></ul></li><li><strong>输出</strong>： I/O microtask</li></ul><p><strong>7. 渲染阶段</strong></p><ul><li><strong>阶段</strong>：浏览器检查是否需要更新 DOM 和渲染。</li><li><strong>执行</strong>： <ul><li>执行 requestAnimationFrame 回调，输出：requestAnimationFrame callback。</li><li>执行 DOM 更新：document.body.style.background = &#39;lightblue&#39;，触发回流（布局计算）和重绘（样式应用）。</li></ul></li><li><strong>输出</strong>： requestAnimationFrame callback</li><li><strong>备注</strong>：HTML 规范保证渲染阶段在定时器阶段之后，但实际渲染（绘制到屏幕）可能因浏览器优化而延迟。requestAnimationFrame 回调会在渲染前执行。</li></ul><p><strong>8. 空闲阶段</strong></p><ul><li><strong>阶段</strong>：当浏览器空闲时，执行 requestIdleCallback 回调。</li><li><strong>执行</strong>： <ul><li>requestIdleCallback 回调执行，输出：requestIdleCallback, timeRemaining: &lt;some number&gt;（具体时间取决于浏览器）。</li></ul></li><li><strong>输出</strong>： requestIdleCallback, timeRemaining: &lt;some number&gt;</li><li><strong>备注</strong>：requestIdleCallback 的执行时机取决于浏览器调度，通常在渲染后或当浏览器空闲时运行。它的优先级低于其他阶段。</li></ul><p><strong>最终输出</strong> Script startScript endInitial Promise microtasksetTimeout callbacksetTimeout microtaskI/O callbackI/O microtaskrequestAnimationFrame callbackrequestIdleCallback, timeRemaining: &lt;some number&gt;</p><p><strong>关键点说明</strong></p><ol><li><strong>事件循环顺序</strong>： <ul><li>每个宏任务（定时器、I/O 回调）执行后，立即清空微任务队列。</li><li>渲染阶段（包括 requestAnimationFrame 和 DOM 更新）在定时器和 I/O 回调之后。</li><li>空闲阶段（requestIdleCallback）优先级最低，通常最后执行。</li></ul></li><li><strong>微任务优先级</strong>： <ul><li>微任务（如 Promise.then）在每个宏任务后立即执行，确保微任务队列清空。</li></ul></li><li><strong>渲染阶段</strong>： <ul><li>requestAnimationFrame 在渲染前运行，适合动画相关操作。</li><li>DOM 更新（如修改样式）可能触发回流和重绘，但实际屏幕绘制由浏览器决定。</li></ul></li><li><strong>空闲阶段</strong>： <ul><li>requestIdleCallback 适合低优先级任务（如后台数据处理），执行时间不保证。</li></ul></li></ol><p><strong>注意事项</strong></p><ul><li><strong>浏览器差异</strong>：requestIdleCallback 和渲染的实际执行时机可能因浏览器优化而略有不同。</li><li><strong>异步模拟</strong>：simulateAsyncIO 使用 setTimeout 模拟 I/O，实际场景可能是 fetch 或文件操作。</li><li><strong>微任务嵌套</strong>：微任务中注册新的微任务（如 setTimeout 回调中的 Promise）会在同一微任务阶段执行。</li></ul><p>如果需要进一步优化代码或针对特定场景分析，请提供更多细节！</p></div>',1)])])}const I=l(s,[["render",r]]);export{_ as __pageData,I as default};
